"use client";

import { ArrowUpRight, Search, X } from "lucide-react";
import { products, photo, money } from "@/data/furniture-products";
import { useCommerceStore } from "@/lib/commerce-store";
import { CartDrawer } from "@/components/cart-drawer";

export function CommerceShell() {
  const drawer = useCommerceStore((state) => state.drawer);
  const query = useCommerceStore((state) => state.query);
  const favorites = useCommerceStore((state) => state.favorites);
  const setDrawer = useCommerceStore((state) => state.setDrawer);
  const setQuery = useCommerceStore((state) => state.setQuery);
  const changeCart = useCommerceStore((state) => state.changeCart);
  const items = products.filter((product) => product.name.toLowerCase().includes(query.toLowerCase()));

  return (
    <>
      <CartDrawer />
      {(drawer === "menu" || drawer === "search" || drawer === "wishlist") && <div className="overlay" onClick={() => setDrawer(null)}>
        <aside className={`drawer ${drawer === "menu" ? "drawer-menu" : ""}`} onClick={(event) => event.stopPropagation()}>
          <div className="drawer-head"><span>{drawer === "wishlist" ? "Vos favoris" : drawer === "search" ? "Rechercher" : "Explorer"}</span><button onClick={() => setDrawer(null)} aria-label="Fermer"><X size={20} /></button></div>
          {drawer === "menu" && <nav className="drawer-menu-links"><a onClick={() => setDrawer(null)} href="/products">Collections <ArrowUpRight /></a><a onClick={() => setDrawer(null)} href="/#histoire">Notre maison <ArrowUpRight /></a><a onClick={() => setDrawer(null)} href="/#newsletter">Le journal <ArrowUpRight /></a></nav>}
          {drawer === "search" && <div className="search-box"><Search size={18} /><input autoFocus placeholder="Canapé, matelas…" value={query} onChange={(event) => setQuery(event.target.value)} /></div>}
          {drawer === "wishlist" && (favorites.length === 0 ? <div className="empty-drawer"><p>Les pièces que vous aimez apparaîtront ici.</p><a href="/products" onClick={() => setDrawer(null)}>Explorer la collection ↗</a></div> : <div className="drawer-items">{products.filter((product) => favorites.includes(product.id)).map((product) => <div className="drawer-item" key={product.id}><img src={photo(product.image, 220)} alt="" /><div><h3>{product.name}</h3><p>{money(product.price)}</p><a className="drawer-add" href="/favorites" onClick={() => setDrawer(null)}>Voir mes favoris</a></div></div>)}</div>)}
          {drawer === "search" && <div className="drawer-items">{items.map((product) => <div className="drawer-item" key={product.id}><img src={photo(product.image, 220)} alt="" /><div><h3>{product.name}</h3><p>{money(product.price)}</p><button className="drawer-add" onClick={() => { changeCart(product.id, 1); setDrawer("cart"); }}>Ajouter au panier +</button></div></div>)}{items.length === 0 && <div className="empty-drawer"><p>Aucun résultat pour « {query} ».</p></div>}</div>}
        </aside>
      </div>}
    </>
  );
}
